def wc(p,rs,fields=None):
 p.parent.mkdir(exist_ok=True,parents=True);fields=fields or list(dict.fromkeys(k for r in rs for k in r))
 with p.open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows({k:('NA' if v is None else v) for k,v in r.items()} for r in rs)
def esc(s):return html.escape(str(s))
def write_paper_readme(path, text):
 previous = path.read_text() if path.exists() else ''
 markers = ['<!-- atlas-guidance -->', '<!-- project-tracing-review-2026-10-31 -->']
 positions = [previous.index(marker) for marker in markers if marker in previous]
 if positions:
  text = text.rstrip() + '\n\n' + previous[min(positions):]
 path.write_text(text)
